export type NotificationKind = "enrollment-confirmed" | "enrollment-rejected";

export interface Notification {
  id: string;
  recipientId: string;
  kind: NotificationKind;
  /** Human-readable text shown to the recipient. */
  message: string;
  /** The enrollment this notification is about. */
  enrollmentId: string;
}
import { BadRequestException, Controller, Get, Query } from "@nestjs/common";
import type { Notification } from "./notification.types.js";
import { NotificationsService } from "./notifications.service.js";

@Controller("notifications")
export class NotificationsController {
  constructor(private readonly notifications: NotificationsService) {}

  @Get()
  list(@Query("recipientId") recipientId?: string): Notification[] {
    if (!recipientId) throw new BadRequestException("recipientId is required");
    return this.notifications.forRecipient(recipientId);
  }
}
import { Module } from "@nestjs/common";
import { NotificationsController } from "./notifications.controller.js";
import { NotificationsService } from "./notifications.service.js";

@Module({
  controllers: [NotificationsController],
  providers: [NotificationsService],
  exports: [NotificationsService],
})
export class NotificationsModule {}
import { describe, it, expect } from "vitest";
import { NotificationsService } from "./notifications.service.js";

describe("NotificationsService", () => {
  it("keeps each recipient's notifications separate, in order", () => {
    const service = new NotificationsService();
    service.notify("stu-ada", "enrollment-confirmed", "enr-1", "first");
    service.notify("stu-bob", "enrollment-rejected", "enr-2", "other");
    service.notify("stu-ada", "enrollment-rejected", "enr-3", "second");

    expect(service.forRecipient("stu-ada").map((n) => [n.id, n.message])).toEqual([
      ["ntf-1", "first"],
      ["ntf-3", "second"],
    ]);
    expect(service.forRecipient("stu-nobody")).toEqual([]);
  });
});
import { Injectable } from "@nestjs/common";
import type { Notification, NotificationKind } from "./notification.types.js";

/**
 * In-memory outbox. Other modules call notify(); recipients read their notifications over HTTP.
 * Delivery is deterministic: IDs are sequential and nothing leaves the process.
 */
@Injectable()
export class NotificationsService {
  private readonly outbox: Notification[] = [];

  notify(recipientId: string, kind: NotificationKind, enrollmentId: string, message: string): Notification {
    const notification: Notification = { id: `ntf-${this.outbox.length + 1}`, recipientId, kind, message, enrollmentId };
    this.outbox.push(notification);
    return notification;
  }

  forRecipient(recipientId: string): Notification[] {
    return this.outbox.filter((n) => n.recipientId === recipientId);
  }
}
import { Injectable, NotFoundException } from "@nestjs/common";
import { NotificationsService } from "../notifications/notifications.service.js";
import { CourseCatalog } from "./course-catalog.js";
import { EnrollmentRepository } from "./enrollment.repository.js";
import type { CourseSummary, Enrollment, EnrollmentRequest, RejectionReason } from "./enrollment.types.js";

/**
 * Enrollment rules. Every decision is recorded and announced to the student:
 * a confirmed enrollment takes a seat; a full course or a repeat request is rejected.
 */
@Injectable()
export class EnrollmentService {
  constructor(
    private readonly catalog: CourseCatalog,
    private readonly enrollments: EnrollmentRepository,
    private readonly notifications: NotificationsService,
  ) {}

  courses(): CourseSummary[] {
    return this.catalog.all().map((c) => ({ ...c, seatsLeft: c.capacity - this.enrollments.confirmedFor(c.id).length }));
  }

  enroll(request: EnrollmentRequest): Enrollment {
    const course = this.catalog.find(request.courseId);
    if (!course) throw new NotFoundException(`unknown course ${request.courseId}`);

    const taken = this.enrollments.confirmedFor(course.id);
    const reason: RejectionReason | undefined = taken.some((e) => e.studentId === request.studentId)
      ? "ALREADY_ENROLLED"
      : taken.length >= course.capacity
        ? "COURSE_FULL"
        : undefined;

    const enrollment = this.enrollments.save({
      id: this.enrollments.nextId(),
      studentId: request.studentId,
      courseId: course.id,
      status: reason ? "rejected" : "confirmed",
      ...(reason ? { reason } : {}),
    });

    if (reason) {
      this.notifications.notify(
        enrollment.studentId,
        "enrollment-rejected",
        enrollment.id,
        reason === "COURSE_FULL" ? `${course.title} is full; your enrollment was not accepted.` : `You are already enrolled in ${course.title}.`,
      );
    } else {
      this.notifications.notify(enrollment.studentId, "enrollment-confirmed", enrollment.id, `You are enrolled in ${course.title}.`);
    }
    return enrollment;
  }

  get(id: string): Enrollment {
    const enrollment = this.enrollments.findById(id);
    if (!enrollment) throw new NotFoundException(`unknown enrollment ${id}`);
    return enrollment;
  }
}
/** Data contracts of the enrollment API. */

export interface Course {
  id: string;
  title: string;
  capacity: number;
}

export type CourseSummary = Course & { seatsLeft: number };

export type EnrollmentStatus = "confirmed" | "rejected";

export type RejectionReason = "COURSE_FULL" | "ALREADY_ENROLLED";

export interface Enrollment {
  id: string;
  studentId: string;
  courseId: string;
  status: EnrollmentStatus;
  /** Set when status is "rejected". */
  reason?: RejectionReason;
}

export interface EnrollmentRequest {
  studentId: string;
  courseId: string;
}

/** Validates an untrusted request body. Returns the request or a list of problems. */
export function parseEnrollmentRequest(body: unknown): EnrollmentRequest | { problems: string[] } {
  const problems: string[] = [];
  const b = (typeof body === "object" && body !== null ? body : {}) as Record<string, unknown>;
  for (const field of ["studentId", "courseId"] as const) {
    if (typeof b[field] !== "string" || !(b[field] as string).trim()) problems.push(`${field} must be a non-empty string`);
  }
  return problems.length ? { problems } : { studentId: (b.studentId as string).trim(), courseId: (b.courseId as string).trim() };
}

